"""Tests for synthstr.stringy module."""

from __future__ import annotations

import pytest

from synthstr.stringy import is_palindrome, reverse, truncate, word_count


# ---------------------------------------------------------------------------
# reverse
# ---------------------------------------------------------------------------

class TestReverse:
    @pytest.mark.parametrize("input_str,expected", [
        ("hello", "olleh"),
        ("abcdef", "fedcba"),
        ("a", "a"),
        ("", ""),
        ("ab", "ba"),
    ])
    def test_reverse_returns_reversed_string(self, input_str: str, expected: str) -> None:
        assert reverse(input_str) == expected

    def test_reverse_is_own_inverse(self) -> None:
        original = "Testing 123!"
        assert reverse(reverse(original)) == original

    def test_reverse_preserves_unicode(self) -> None:
        assert reverse("café") == "éfac"

    def test_reverse_handles_whitespace_and_punctuation(self) -> None:
        assert reverse("a b c") == "c b a"


# ---------------------------------------------------------------------------
# is_palindrome
# ---------------------------------------------------------------------------

class TestIsPalindrome:
    @pytest.mark.parametrize("s", [
        "racecar",
        "madam",
        "A man, a plan, a canal: Panama",
        "Was it a car or a cat I saw?",
        "",
        "a",
    ])
    def test_palindromes_return_true(self, s: str) -> None:
        assert is_palindrome(s) is True

    @pytest.mark.parametrize("s", [
        "hello",
        "python",
        "abcdef",
        "almost racecar",
    ])
    def test_non_palindromes_return_false(self, s: str) -> None:
        assert is_palindrome(s) is False

    def test_ignores_case(self) -> None:
        assert is_palindrome("RaceCar") is True

    def test_ignores_non_alphanumeric(self) -> None:
        assert is_palindrome("!@#a#@!") is True

    def test_digits_treated_as_characters(self) -> None:
        assert is_palindrome("12321") is True
        assert is_palindrome("12345") is False


# ---------------------------------------------------------------------------
# word_count
# ---------------------------------------------------------------------------

class TestWordCount:
    @pytest.mark.parametrize("s,expected", [
        ("hello world", 2),
        ("one", 1),
        ("the quick brown fox", 4),
        ("  leading  spaces  ", 2),
    ])
    def test_counts_whitespace_delimited_words(self, s: str, expected: int) -> None:
        assert word_count(s) == expected

    def test_empty_string_returns_zero(self) -> None:
        assert word_count("") == 0

    def test_only_whitespace_returns_zero(self) -> None:
        assert word_count("   \t\n  ") == 0

    def test_tabs_and_newlines_are_delimiters(self) -> None:
        assert word_count("a\tb\nc") == 3


# ---------------------------------------------------------------------------
# truncate
# ---------------------------------------------------------------------------

class TestTruncate:
    def test_short_string_returned_unchanged(self) -> None:
        assert truncate("hi", 10) == "hi"

    def test_string_at_exact_limit_returned_unchanged(self) -> None:
        assert truncate("hello", 5) == "hello"

    def test_string_exceeding_limit_is_truncated_with_ellipsis(self) -> None:
        result = truncate("hello world", 6)
        assert result == "hello\u2026"
        assert len(result) == 6

    def test_truncation_replaces_last_character_with_ellipsis(self) -> None:
        result = truncate("abcdef", 4)
        assert result == "abc\u2026"

    def test_limit_of_one_returns_single_ellipsis(self) -> None:
        result = truncate("abcdef", 1)
        assert result == "\u2026"

    def test_limit_of_zero_returns_empty(self) -> None:
        assert truncate("anything", 0) == ""

    def test_negative_limit_raises_value_error(self) -> None:
        with pytest.raises(ValueError, match="limit must be non-negative"):
            truncate("hello", -1)

    def test_empty_string_with_zero_limit(self) -> None:
        assert truncate("", 0) == ""

    def test_empty_string_with_positive_limit(self) -> None:
        assert truncate("", 5) == ""

    @pytest.mark.parametrize("limit", [1, 2, 5, 10, 100])
    def test_result_never_exceeds_limit(self, limit: int) -> None:
        result = truncate("a long string that should be truncated", limit)
        assert len(result) <= limit

